css:
.sl-continue-learning.sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-continue-learning .sl-text-primary { color: var(--smartlearn-primary); }
.sl-continue-learning .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-continue-learning .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-continue-learning .sl-bg-card { background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border); }
.sl-continue-learning .sl-border { border-color: var(--smartlearn-card-border); }
.sl-continue-learning .sl-card-radius { border-radius: var(--smartlearn-radius, 1rem); }
.sl-continue-learning h2, .sl-continue-learning h3, .sl-continue-learning h4 { font-family: var(--smartlearn-heading-font, inherit); }
.sl-continue-learning .sl-tracking-wide { letter-spacing: 0.1em; }
.sl-continue-learning .sl-media-fallback { background-color: var(--smartlearn-card-bg); }
.sl-continue-learning .sl-resume-circle {
    width: 60px;
    height: 60px;
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    transition: transform 0.2s ease, background-color 0.2s ease;
}
.sl-continue-learning .sl-resume-circle .fa-play { margin-inline-start: 0.2rem; }
[dir="rtl"] .sl-continue-learning .sl-resume-circle .fa-play { transform: scaleX(-1); }
.sl-continue-learning .sl-resume-circle:hover { background-color: var(--smartlearn-btn-hover-bg); transform: translate(-50%, -50%) scale(1.06); }
.sl-continue-learning .sl-progress-track {
    height: 8px;
    background-color: var(--smartlearn-bg);
    background-color: color-mix(in oklab, var(--smartlearn-text) 14%, var(--smartlearn-card-bg));
}
.sl-continue-learning .sl-progress-fill { background-color: var(--smartlearn-primary); }
.sl-continue-learning .sl-icon-box {
    background-color: var(--smartlearn-bg);
    background-color: color-mix(in oklab, var(--smartlearn-primary) 14%, var(--smartlearn-card-bg));
}
.sl-continue-learning .sl-btn-primary {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    border: 1px solid var(--smartlearn-btn-bg);
    transition: background-color 0.2s ease, border-color 0.2s ease;
}
.sl-continue-learning .sl-btn-primary:hover,
.sl-continue-learning .sl-btn-primary:focus-visible {
    background-color: var(--smartlearn-btn-hover-bg);
    border-color: var(--smartlearn-btn-hover-bg);
    color: var(--smartlearn-btn-text);
}
.sl-continue-learning .sl-btn-outline {
    background-color: transparent;
    color: var(--smartlearn-text);
    border: 1px solid var(--smartlearn-card-border);
    transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}
.sl-continue-learning .sl-btn-outline:hover,
.sl-continue-learning .sl-btn-outline:focus-visible {
    background-color: var(--smartlearn-btn-bg);
    border-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
}
.sl-continue-learning .sl-hover-row { transition: background-color 0.2s ease; }
@media (hover: hover) {
    .sl-continue-learning .sl-hover-row:hover { background-color: var(--smartlearn-bg); }
}
.sl-continue-learning .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}
@media (prefers-reduced-motion: reduce) {
    .sl-continue-learning .sl-resume-circle,
    .sl-continue-learning .sl-btn-primary,
    .sl-continue-learning .sl-btn-outline,
    .sl-continue-learning .sl-hover-row { transition: none; }
}
@media (min-width: 992px) {
    .sl-continue-learning { padding-top: 6rem !important; padding-bottom: 6rem !important; }
}
